"""Finalize evidence-based Chinese P4-C1 report and seals; CPU only."""
from c1_common import *
import datetime,subprocess,collections
from zoneinfo import ZoneInfo
CONDITIONS=['G0S0','G0S1','G1S0','G1S1']
def run():
 validation=json.loads((R/'validation.json').read_text());assert validation['passed']
 m=json.loads((R/'counterfactual_metrics.json').read_text());b=json.loads((R/'baseline_validation.json').read_text());inter=json.loads((R/'interpretation.json').read_text());gts=list(csv.DictReader((R/'per_GT_counterfactual.csv').open()));index={(int(x['sample_idx']),int(x['gt_idx']),x['condition']):x for x in gts}
 key=list(csv.DictReader((R/'key_case_summary.csv').open()));allchange=list(csv.DictReader((R/'GT_changed_targets.csv').open()));anchor_evidence=list(csv.DictReader((R/'key_case_anchor_evidence.csv').open()))
 max_geo=max(v for c in b['cases'] for v in c['max_geometry_error'].values());max_score=max(v for c in b['cases'] for v in c['max_score_error'].values())
 ties={c:{t:len(v['score'])-len(set(v['score'])) for t,v in stats.items()} for c,stats in json.loads((R/'aggregate_native_stats.json').read_text()).items()}
 max_quality=max(int(x['quality_pass']) for x in csv.DictReader((R/'per_case_metrics.csv').open()))
 local_ties=[]
 for d in ['baseline','counterfactual']:
  for p in (R/d).glob('*.json'):local_ties.append(json.loads(p.read_text())['NMS_tied_score_entries'])
 matching_comp=sum(int(x['matching_competition_FN_despite_final_strict_candidate']) for x in gts)
 lines=['# LRCP P4-C1：全原始Anchor分类分数交叉反事实实验','', '**P4-C1完成，仅CPU。** 固定G1几何后用S0替换全12800 anchor分类输出，6个焦点α1损失中恢复2个（821/GT2、941/GT8），均通过NMS保留选择变化实现；其余4个未恢复。全部162GT的TP70由G1S1的134降至G1S0的132，不能把两例恢复称为整体改善。','', '结果限定保存的head输出层反事实，非训练后模型性能；18例按历史结局分层选取，不是910总体的无偏样本。原P4-Pilot worker FAILED及退出码1保留，未启动PPU、未重新预处理/采集，新增完整forward为0。','',f"完成时间：{datetime.datetime.now(ZoneInfo('Asia/Shanghai')).isoformat()}。输出目录：`{R}`。",'', '## 首要CPU基线验收','',f"全部36个核心原始条件调用原VoxelPostprocessor.post_process，从保存的FP32 cls/reg/dir及冻结anchor/变换矩阵重新解码，沿sigmoid→score>0.2→方向纠正→原尺寸/z→top1000→polygon NMS(IoU>0.15)→range→原eval_utils。角点/解码最大绝对误差{max_geo:.12g}m，score最大误差{max_score:.12g}，分别在预声明1e-5/1e-6内。没有以保存后的框或分数替换CPU重放失败项。",'', '所有12800 score门限mask、质量mask、每阶段原anchor索引、NMS keep及顺序、range mask、预测→GT匹配与TP70/FN70、每个GT每阶段的严格候选ID/数量及IoU≥0.7分类都与P4-Pilot一致。36组全部通过后才执行反事实。baseline_validation.json逐例记录误差和验收。','', 'S交换采用完整cls logits移植，在原CPU float32 sigmoid内形成12800分数；与保存的PPU分数只有上述舍入差。四条件均使用相同CPU实现；固定G的reg/dir/anchor、全解码角点逐位相等，CF分数逐位等于相应S的CPU基线。没有GT指导替换、局部挑anchor、重新标定、阈值调整或沿用TP/FP/NMS keep。','', '原anchor flat index=((y*80)+x)*2+r，只是计算网格对应，不是真实车辆身份。原生GT匹配通过精确函数帧trace记录pop的GT索引，使用修复后的CPU tensor适配，不再把NumPy数组直接传给tensor-only评估接口。','', '## A：四组匹配结果','', '| GT范围 / TP70数量 | G0S0 | G0S1 | G1S0 | G1S1 |','|---|---:|---:|---:|---:|']
 for label,k in [('6个焦点损失','loss_TP70_to_FN70'),('6个焦点恢复','gain_FN70_to_TP70'),('6个双TP控制','control_TP70_to_TP70'),('全部18个焦点','all_focal'),('全部162个GT','all_GT')]:lines.append('| '+label+' | '+' | '.join(str(m['GT_group_metrics'][k][c]['TP70']) for c in CONDITIONS)+' |')
 lines+=['', '| 条件 | 全部GT TP70 / FN70 | FP70 | 最终预测数 |','|---|---:|---:|---:|']
 for c in CONDITIONS:
  q=m['metrics'][c]['70'];lines.append(f"| {c} | {q['TP']} / {q['FN']} | {q['FP']} | {q['predictions']} |")
 lines+=['', '固定G0，S0→S1：131个TP保持、6个FN→TP、1个TP→FN、24个FN保持（净+5TP）。固定G1，S1→S0：130个TP保持、2个FN→TP、4个TP→FN、26个FN保持（净−2TP）。每组都重新执行所有后处理及原生贪心匹配，没有固定原始标签。','', '### 全部18个焦点目标','', '| sample / GT | 原分组 | G0S0 | G0S1 | G1S0 | G1S1 |','|---|---|---|---|---|---|']
 short={'score_filter':'FN(score)','nms_overlap_suppression':'FN(NMS)','no_high_iou_raw_candidate':'FN(raw)','size_or_z_filter':'FN(quality)','nms_top1000_truncation':'FN(top1000)','post_nms_range_filter':'FN(range)','high_iou_survives_final':'FN(match)'}
 for sel in chosen():
  sid=int(sel['sample_idx']);gi=int(sel['gt_idx']);cells=[]
  for c in CONDITIONS:
   q=index[(sid,gi,c)];cells.append('TP #'+q['matched_anchor_id'] if int(q['final_TP70']) else short[q['availability_class']])
  lines.append(f"| {sid}/{gi} | {sel['group'].split('_')[0]} | "+' | '.join(cells)+' |')
 lines+=['', '![18个预定焦点GT四条件对照](figures/focal_GT_four_conditions.png)','', '## B、C：两个恢复目标与NMS选择','', '六个原α1损失中，G1S0只恢复821/GT2与941/GT8。两个目标在S0/S1下通过score的严格候选集合分别保持3个和2个，没有通过新增严格候选准入恢复；真实NMS保留了不同anchor。完整NMS重放逐位等于原生keep。','', '| sample / GT | 恢复anchor | 固定G1 IoU_GT | S1→S0分数 | 原S1 suppressor | suppressor的S1→S0分数 |','|---|---:|---:|---|---:|---|']
 for sid,gi,ai,su in [(821,2,10433,10593),(941,8,7166,7164)]:
  a=next(x for x in anchor_evidence if int(x['sample_idx'])==sid and int(x['anchor_id'])==ai);u=next(x for x in anchor_evidence if int(x['sample_idx'])==sid and int(x['anchor_id'])==su)
  lines.append(f"| {sid}/{gi} | {ai} | {float(a['IoU_G1']):.9f} | {float(a['score_S1']):.6f}→{float(a['score_S0']):.6f} | {su} | {float(u['score_S1']):.6f}→{float(u['score_S0']):.6f} |")
 lines+=['', '821中S1优先保留#10593（G1 IoU=0.695717），压制#10433（0.749506）；换S0后优先级反转并保留#10433。941中S1优先保留#7164（0.693147），压制#7166（0.720510）；换S0后反转。这些anchor在G0中的IoU都≥0.7，因此相同分数选择变化在G0仍可保持TP，说明分数排序与几何质量相互作用，不能把原始α0/α1差异全部划给分类头。','', '![821/GT2四组BEV对照](figures/case_sample_821_GT_2.png)','', '## D：四个未恢复目标','', '| sample / GT | G1 raw严格候选ID | G1S1：raw/score/NMS/final | G1S0：raw/score/NMS/final | 结果 |','|---|---|---|---|---|']
 for x in key:
  sid=int(x['sample_idx']);gi=int(x['gt_idx']);a=index[(sid,gi,'G1S1')];n=index[(sid,gi,'G1S0')]
  count=lambda q:'/'.join(q['count_ge70_'+k] for k in ['raw_decoded','score_pass','nms_keep','final_range'])
  lines.append(f"| {sid}/{gi} | {x['G1_raw_strict_ids']} | {count(a)} | {count(n)} | {'恢复TP70' if int(x['restored']) else short[n['availability_class']]} |")
 lines+=['', '- **17/GT5**：G1严格候选#8939、#9097在S0下最高分0.188218，仍未超过0.2。G0原匹配#8777的IoU从G0的0.865328变成G1的0.545211；不能把G0高分anchor当作G1仍然几何正确的框。','- **918/GT6**：G1严格候选#603、#605在S0下最高分0.157439，同样无法通过score。G0原匹配#925在G1的IoU只有0.374105。此目标在固定G0使用S1也由TP→FN（11个raw严格候选全部在score消失），提供分数门限效应的反向证据，但不能据此说G1换S0能恢复。','- **670/GT3**：#6028分数0.158407→0.314553，score后严格候选从0增加到1，随后仍被#6186压制。#6186的S0分数0.722929、G1 IoU=0.672138，两框NMS IoU=0.849737。这里最后消失阶段从score转移到NMS，**通过门限不等于恢复TP**。其余3个raw严格候选仍未通过S0门限，完整四候选链见CSV。','- **486/GT2**：两个分数条件均保留#6278；其G0 IoU=0.703849、G1 IoU=0.696731。其他严格候选仍被压制，例如#6440的S0分数0.271607低于#6278的0.567790；单纯换S0没有改变关键优先关系。G1 raw仍有4个严格候选，不能将此例叫作raw几何集合完全缺候选。','', '上述四例不支持“缺少任何高IoU raw候选”的解释，而是证明S0与G1几何并非无损可移植：高分anchor位置/回归质量变化，以及候选间NMS竞争会限制恢复。这里没有独立测试最优分数、其他阈值或模型内部因果干预。','', '## C：新增退化与其他目标','', 'G1换S0新增的4个TP→FN为184/GT2、360/GT5、683/GT7（均最后在NMS丢尽严格候选）以及895/GT2（score丢尽）。恢复组6例中297/GT10、499/GT3、683/GT4、895/GT0仍为TP，184/GT2和360/GT5退化；6个双TP控制全部四条件均为TP。','', 'G0换S1：6个FN→TP为297/GT9、683/GT4、683/GT7、821/GT4、895/GT0、895/GT2；其中恢复后保留候选原先首删因为score的3个、NMS的3个。唯一TP→FN是918/GT6（score）。全部变化包括非焦点GT，详见GT_changed_targets.csv；不是只统计恢复成功者。','', f'全部72个条件的quality后候选最多{max_quality}个，未触发top1000截断。全部648个GT条件中“最终有严格候选却因贪心竞争为FN”的计数为{matching_comp}，这也是重新匹配后的实测结果。','', '## 描述性PR/AP与科学边界','', '| 条件 | AP50（18例） | AP70（18例） |','|---|---:|---:|']
 for c in CONDITIONS:lines.append(f"| {c} | {m['metrics'][c]['50']['AP_descriptive_selected18']:.10f} | {m['metrics'][c]['70']['AP_descriptive_selected18']:.10f} |")
 lines+=['', '![18例描述性PR](figures/PR_descriptive_selected18.png)','', '本集合G1S1的AP70高于G0S0，与910总体已知方向不同，进一步说明结果分层选样的AP不是总体估计。G0换S1的AP70升高，G1换S0反而降低；不能将S0视为跨几何条件普遍更好的分类分数，也不能把反事实结果称为训练后的模型改善。','', f'局部NMS输入最大同分条目数={max(local_ties)}；全局分数并列条目数={json.dumps(ties,ensure_ascii=False)}。正式NMS始终用原scores.argsort()[::-1]及top1000，eval用原np.argsort(-score)，没有换稳定排序。全局PR/AP按sample_idx升序聚合，与原loader子集顺序一致。PR_global_ranking.csv保存完整分数排序。','', '## E：支持与反驳的假设','', '**H1得到限定支持。** 在固定G1、几何完全不变时，完整S0移植使2个焦点损失FN→TP，真实机制为NMS保留优先级变化。固定G0的918/GT6又由S1直接造成score丢尽，证明分数门限也能改变严格匹配。所有效果均为本保存head层反事实，可被上述相反方向和失败案例检验。','', '**H2得到限定支持。** 4个原损失不能恢复，而且全162GT存在4个新增退化。17/918是严格候选的供体分数仍不足门限，670是准入后被抑制，486是关键错误候选的几何低于0.7且优先关系未改。这些证据支持跨条件分数与几何耦合的限制，不能进一步断言“剩余损失全是纯几何”或“offset必定预测错”。','', '反驳的简单解释包括“把S0全部移植就能恢复所有α1严格损失”“S1对任意固定几何都更坏”“raw存在严格候选就一定能恢复”。G0几何下360/GT5没有任何raw严格候选，即使用S1也无法成为TP，说明分数不能凭空生成几何候选；这不代表其他未恢复病例也缺raw候选。','', '本轮没有重运行融合/offset/检测头，只使用其保存输出；MetaFlow在真实模型中可同时影响分类和回归。C1的score替换改变score门限与NMS输入/排序，不能把它们当成独立模块的因果贡献之和，也不提供训练可达到的性能保证。','', '## F：下一步最小验证','', '目前不建议直接扩展910采集来代替机制辨析。先用已有输出对这些案例设计小型CPU的“score准入来源×NMS排序来源”分离诊断，明确它是新协议而非偷偷改变本次阈值；可检验670等准入恢复后仍失败的原因，无需PPU。若研究目标转为判定MetaFlow内部补偿责任，再设计6个损失加少量恢复/控制的融合/offset内部干预，使用同一冻结batch并先审阅采集点及预算；任何PPU必须新授权且由用户终端启动。','', '本次没有执行这些后续干预，也没有扩展样本。910样本可在机制与泛化研究目标、样本代表性、预算和输出流式策略明确后单独批准。','', '## 交付、复现与追溯','', '- PROTOCOL.md：在基线执行前保存的协议和容差。','- baseline_validation.json：36组首要门；counterfactual_metrics.json：四组指标及迁移。','- per_GT_counterfactual.csv：648行，含全部阶段高IoU候选ID、数量、匹配与变化；focal_GT_counterfactual.csv：72行焦点子集。','- per_anchor_changes.csv：460800行，覆盖每个固定G的全部12800 anchor，原/交换分数及完整状态。','- nms_changes.csv：1933行，覆盖NMS输入并集及keep/suppressor变化。','- per_GT_anchor_lineage.csv：3466行，全部GT的每个raw严格候选原/交换删除链和suppressor，不只一个最佳框。','- key_case_summary.csv、key_case_anchor_evidence.csv、GT_changed_targets.csv：六例与所有恢复/退化目标的便捷证据表。','- baseline/与counterfactual/：72组完整CPU后处理数组/分数/lineage与原生匹配。','- figures/：6个损失目标四条件BEV、18焦点汇总、TP计数、PR，共9图各PNG/PDF。图内绘出所有raw严格框；为可读性只给最高分严格候选、匹配框及抑制框加文字标签，完整ID和数值在CSV。','- validation.json：独立重读72组、原生重新匹配/NMS、质量/range及全CSV一致性。','', '复现：把本目录全部.py、run_cpu.sh、inputs.json、SAMPLE_SELECTION.csv、SELECTED_SAMPLES_ALL_GT.csv和PROTOCOL.md复制到新的空P4_C1目录，运行该新目录run_cpu.sh。脚本锁定历史输入，拒绝覆盖已有结果，全程隐藏CUDA设备并按baseline→反事实→独立验收→图表→报告顺序执行。当前目录不重复执行。','', f"CPU基线{b['elapsed_seconds']:.3f}秒、反事实{m['elapsed_seconds']:.3f}秒、独立验收{validation['elapsed_seconds']:.3f}秒。新增模型forward=0；CUDA未初始化。原242个历史产物和3310个受保护文件哈希一致，原worker FAILED/退出码1保持。" ]
 with (R/'REPORT.md').open('x') as f:f.write('\n'.join(lines)+'\n')
 # Recheck all protected inputs after figure/report work.
 changed=[p for p,h in {**INPUT['history_hashes'],**INPUT['protected_hashes']}.items() if sha_file(p)!=h]
 assert not changed,changed
 save(R/'DIFF_AUDIT.json',{'passed':True,'history_files':len(INPUT['history_hashes']),'protected_files':len(INPUT['protected_hashes']),'changed':changed,'original_worker_state':'FAILED','original_exit_code':1,'scope':'new P4_C1 directory only'})
 ast_files=[]
 for p in R.glob('*.py'):compile(ast.parse(p.read_text()),str(p),'exec');ast_files.append(p.name)
 subprocess.run(['bash','-n',str(R/'run_cpu.sh')],check=True)
 guard()
 save(R/'COMPLETION.json',{'phase':'P4-C1','completed':True,'baseline_passed':True,'validation_passed':True,'sample_count':18,'GT_count':162,'condition_count':4,'postprocess_cases':72,'model_forwards':0,'CUDA_initialized':False,'restored_loss_GT_count':inter['restored_loss_GT_count'],'unrestored_loss_GT_count':inter['unrestored_loss_GT_count'],'TP70_all_GT':{c:m['metrics'][c]['70']['TP'] for c in CONDITIONS},'TP70_all_focal':{c:m['GT_group_metrics']['all_focal'][c]['TP70'] for c in CONDITIONS},'static_compiled_files':ast_files,'shell_syntax_passed':True,'original_P4_worker_state_preserved':'FAILED','original_worker_exit_code_preserved':1,'run_directory':str(R),'peak_RSS_this_report_process_bytes':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss*1024,'completed_at_Asia_Shanghai':datetime.datetime.now(ZoneInfo('Asia/Shanghai')).isoformat()})
 with (R/'ARTIFACTS.sha256').open('x') as f:
  for p in sorted(R.rglob('*')):
   if p.is_file() and p.name!='ARTIFACTS.sha256' and p.name not in ['report.log','execution.jsonl']:f.write(sha_file(p)+'  '+str(p.relative_to(R))+'\n')
 print('P4_C1_COMPLETED_CPU_ONLY',flush=True)
if __name__=='__main__':run()
